using FluNET.Compilation;using FluNET.Context;namespace FluNET.Tests.Compilation;[TestFixture]public sealed class SqlProviderTests{[Test]public void SqlResourceCompilesToTypedReadFrame(){using FluNETContext c=SurfaceCompilationExtensions.CreateSurfaceContext();SurfaceCompilationResult r=c.CompileSurface("GET sql:\"SELECT id, name FROM users\" AS users");Assert.That(r.IsValid,Is.True,string.Join(" | ",r.Lowering.Diagnostics.Select(d=>d.Message)));Assert.Multiple(()=>{Assert.That(r.BoundProgram!.Commands.Single().Frame.Id.Value,Is.EqualTo("surface.get.sql"));Assert.That(r.TypedProgram!.Commands.Single().ResultType.Name,Does.StartWith("List<"));});}}
